        # 注意：此方法与get_file_content使用相同的端点，但对于目录会返回列表
        endpoint = f"/repos/{owner}/{repo}/contents/{path}"
        params = {}
        if ref:
            params["ref"] = ref

        return await self._request("GET", endpoint, params=params)

